      "path": "internal/protocolserver/failover_dispatch.go",
      "content": "// Package aimodel — failover_dispatch.go\n//\n// Mid-request failover for the priority routing tactic, built as a\n// layered hand-off rather than a smart shim fused into the main path:\n//\n//   - Producer (the protocol handler) emits chunks normally, unaware of\n//     failover. On its first real stream chunk it raises one signal,\n//     CommitFirstChunk, and otherwise does nothing differently.\n//   - firstChunkGate is a passive, protocol-agnostic byte buffer. It\n//     makes no decisions: it records writes until CommitFirstChunk (or\n//     the orchestrator's terminal flush) lets them through.\n//   - Orchestrator (dispatchWithPriorityFailover) owns the retry\n//     decision. It reads the gate's committed/status state after each\n//     attempt and either commits, discards + retries the next tier, or\n//     flushes the buffered terminal error.\n//\n// Single-service requests skip the gate entirely, so the common case\n// never touches the buffer.\n\npackage protocolserver\n\nimport (\n\t\"bytes\"\n\t\"maps\"\n\t\"net/http\"\n\n\t\"github.com/gin-gonic/gin\"\n\t\"github.com/sirupsen/logrus\"\n\t\"github.com/tingly-dev/tingly-box/internal/client\"\n\t\"github.com/tingly-dev/tingly-box/internal/constant\"\n\t\"github.com/tingly-dev/tingly-box/internal/recording\"\n\n\t\"github.com/tingly-dev/tingly-box/internal/loadbalance\"\n\t\"github.com/tingly-dev/tingly-box/internal/protocol\"\n\t\"github.com/tingly-dev/tingly-box/internal/protocol/stream\"\n\t\"github.com/tingly-dev/tingly-box/internal/typ\"\n)\n\n// preStreamErrorRecorder narrows the recorder contract to what\n// pre-stream failure sites need — both *ProtocolRecorder and\n// *streamRecorder fit.\ntype preStreamErrorRecorder interface {\n\tRecordError(error)\n}\n\n// handlePreStreamFailure emits the canonical \"upstream failed\n// pre-stream\" response: status 500 + JSON error, captured by the\n// buffered failover writer so the orchestrator can retry the next\n// priority tier.\nfunc (ph *ProtocolHandler) handlePreStreamFailure(c *gin.Context, err error, recorder preStreamErrorRecorder) {\n\tph.trackUsageFromContext(c, 0, 0, err)\n\tstream.SendStreamingError(c, err)\n\tif recorder != nil {\n\t\trecorder.RecordError(err)\n\t}\n}\n\n// failAttemptSetup reports an in-attempt setup failure — target/endpoint\n// resolution, the pre-transform chain, or the transform itself — that happens\n// before any upstream call. It always writes a 500-class status, which the\n// failover gate buffers and treats as retryable, so the orchestrator advances\n// to the next candidate (possibly a different API style) instead of terminating\n// the whole request on one misconfigured provider. Genuine client errors are\n// rejected in the prologue, before the gate is installed, so they remain\n// non-retryable and reach the client unchanged.\nfunc (ph *ProtocolHandler) FailAttemptSetup(c *gin.Context, err error) {\n\twriteErrorResponse(c, http.StatusInternalServerError, ErrorResponse{\n\t\tError: ErrorDetail{\n\t\t\tMessage: protocol.UpstreamMessage(err),\n\t\t\tType:    \"api_error\",\n\t\t},\n\t})\n}\n\n// retryableUpstreamStatuses are the HTTP status codes treated as\n// \"upstream transiently sick, try the next priority tier\".\n//\n// 500 is included because in-process error helpers (SendStreamingError,\n// SendErrorResponse on forwarding failure) wrap upstream pre-stream\n// errors as 500. 502 covers the explicit \"upstream stream failed\" path.\n// Keeping both means refactors that change one helper's status code\n// don't silently break failover.\n//\n// 401/403 are here because an upstream auth failure is a property of one\n// credential, not of the request: an OAuth token caught mid-refresh, a rotated\n// or revoked API key, a provider-side quota flag. The inbound caller's own\n// token is checked by middleware long before the gate is installed, so a 401\n// reaching this point always came from a provider — and answering it with a\n// sibling service is the whole reason a rule holds more than one. Without\n// this, a single stale credential turns into \"Please run /login\" on the\n// client while healthy services sit idle.\nvar retryableUpstreamStatuses = map[int]bool{\n\thttp.StatusUnauthorized:        true,\n\thttp.StatusForbidden:           true,\n\thttp.StatusTooManyRequests:     true,\n\thttp.StatusBadGateway:          true,\n\thttp.StatusServiceUnavailable:  true,\n\thttp.StatusGatewayTimeout:      true,\n\thttp.StatusInternalServerError: true,\n}\n\n// isRetryableStatus reports whether a buffered status code from a\n// dispatch attempt should trigger failover. Status 0 means the writer\n// was never touched — treat as terminal (the handler ran to completion\n// without writing, retrying would just repeat the no-op).\nfunc isRetryableStatus(status int) bool {\n\treturn status != 0 && retryableUpstreamStatuses[status]\n}\n\n// firstChunkGate is a passive, protocol-agnostic byte buffer placed\n// between a dispatch attempt and the real response writer. It makes no\n// decisions of its own: it records writes into a buffer until an\n// explicit signal commits them. The retry decision lives in the\n// orchestrator; the \"first real chunk arrived\" signal comes from the\n// streaming producer via CommitFirstChunk.\n//\n// Lifecycle:\n//   - buffered  — Write/WriteHeader capture into buf/hdr/status.\n//   - committed — after CommitFirstChunk or CommitIfBuffered, all I/O\n//     passes straight through to the real writer.\n//   - discarded — Discard resets the buffer for the next retry tier\n//     (valid only while uncommitted).\ntype firstChunkGate struct {\n\tgin.ResponseWriter\n\treal      gin.ResponseWriter\n\tbuf       bytes.Buffer\n\thdr       http.Header\n\tstatus    int\n\tcommitted bool\n}\n\nfunc newFirstChunkGate(w gin.ResponseWriter) *firstChunkGate {\n\treturn &firstChunkGate{\n\t\tResponseWriter: w,\n\t\treal:           w,\n\t\thdr:            http.Header{},\n\t}\n}\n\nfunc (g *firstChunkGate) Header() http.Header {\n\tif g.committed {\n\t\treturn g.real.Header()\n\t}\n\treturn g.hdr\n}\n\nfunc (g *firstChunkGate) Write(p []byte) (int, error) {\n\tif g.committed {\n\t\treturn g.real.Write(p)\n\t}\n\tif g.status == 0 {\n\t\tg.status = http.StatusOK\n\t}\n\treturn g.buf.Write(p)\n}\n\nfunc (g *firstChunkGate) WriteString(s string) (int, error) {\n\treturn g.Write([]byte(s))\n}\n\nfunc (g *firstChunkGate) WriteHeader(code int) {\n\tif g.committed {\n\t\tg.real.WriteHeader(code)\n\t\treturn\n\t}\n\tg.status = code\n}\n\n// WriteHeaderNow is swallowed while buffered, delegated once committed.\nfunc (g *firstChunkGate) WriteHeaderNow() {\n\tif g.committed {\n\t\tg.real.WriteHeaderNow()\n\t}\n}\n\n// Flush is a no-op while buffered (so partial SSE can't leak past the\n// gate before commit) and delegates once committed (so streaming clients\n// keep getting incremental delivery). ProcessStream type-asserts the\n// writer for http.Flusher, so this method must exist concretely.\nfunc (g *firstChunkGate) Flush() {\n\tif !g.committed {\n\t\treturn\n\t}\n\tif f, ok := g.real.(http.Flusher); ok {\n\t\tf.Flush()\n\t}\n}\n\n// Status returns the captured status: 0 while untouched, the recorded\n// code otherwise (Write defaults it to 200). Once committed it reflects\n// the real writer. The orchestrator treats 0 as terminal (non-retryable).\nfunc (g *firstChunkGate) Status() int {\n\tif g.committed {\n\t\treturn g.real.Status()\n\t}\n\treturn g.status\n}\n\nfunc (g *firstChunkGate) Size() int {\n\tif g.committed {\n\t\treturn g.real.Size()\n\t}\n\treturn g.buf.Len()\n}\n\nfunc (g *firstChunkGate) Written() bool {\n\tif g.committed {\n\t\treturn g.real.Written()\n\t}\n\treturn g.buf.Len() > 0 || g.status != 0\n}\n\n// Committed reports whether the gate has flushed to the wire. Once\n// committed, retry is impossible — bytes have left the process.\nfunc (g *firstChunkGate) Committed() bool {\n\treturn g.committed\n}\n\n// CommitFirstChunk is the producer's \"first real chunk arrived\" signal.\n// It flushes captured headers + status + buffered body to the real\n// writer and switches to pass-through. Idempotent.\nfunc (g *firstChunkGate) CommitFirstChunk() {\n\tg.commit()\n}\n\n// CommitFirstChunkIfGate signals \"first real chunk arrived\" if w is\n// currently a *firstChunkGate (installed by DispatchWithPriorityFailover\n// when a rule has more than one active service), no-op otherwise. Exported\n// so callers outside this package that simulate a streaming success (e.g.\n// the load-balance dry-run simulator) can commit the gate without needing\n// firstChunkGate itself exported. Returns whether a gate was found and\n// committed.\nfunc CommitFirstChunkIfGate(w gin.ResponseWriter) bool {\n\tgate, ok := w.(*firstChunkGate)\n\tif !ok {\n\t\treturn false\n\t}\n\tgate.CommitFirstChunk()\n\treturn true\n}\n\n// CommitIfBuffered is the orchestrator's deferred terminal flush of an\n// uncommitted buffered response (the last error after retries are\n// exhausted). No-op when already committed or never touched.\nfunc (g *firstChunkGate) CommitIfBuffered() {\n\tif g.committed || (g.buf.Len() == 0 && g.status == 0) {\n\t\treturn\n\t}\n\tg.commit()\n}\n\n// commit copies captured headers, status, and body to the real writer\n// and enters pass-through mode. gin defers WriteHeader to the first\n// Write or WriteHeaderNow, so for body-less responses WriteHeaderNow is\n// forced explicitly.\nfunc (g *firstChunkGate) commit() {\n\tif g.committed {\n\t\treturn\n\t}\n\tg.committed = true\n\tdst := g.real.Header()\n\tmaps.Copy(dst, g.hdr)\n\tstatus := g.status\n\tif status == 0 {\n\t\tstatus = http.StatusOK\n\t}\n\tg.real.WriteHeader(status)\n\tif g.buf.Len() > 0 {\n\t\t_, _ = g.real.Write(g.buf.Bytes())\n\t\tg.buf.Reset()\n\t} else {\n\t\tg.real.WriteHeaderNow()\n\t}\n}\n\n// Discard resets captured state for the next retry tier. No-op once committed.\nfunc (g *firstChunkGate) Discard() {\n\tif g.committed {\n\t\treturn\n\t}\n\tg.buf.Reset()\n\tg.status = 0\n\tfor k := range g.hdr {\n\t\tdelete(g.hdr, k)\n\t}\n}\n\n// selectFallbackService picks the next priority tier excluding services\n// already tried in this request. requireAPIStyle, when non-empty, restricts\n// candidates to one API style; callers that re-transform the request per\n// attempt pass \"\" so the pool can span heterogeneous styles\n// (Anthropic/OpenAI/Google) and failover can rotate freely across providers.\n//\n// Returns (nil, nil, nil) when no compatible candidate remains.\nfunc (ph *ProtocolHandler) selectFallbackService(\n\trule *typ.Rule,\n\texcluded map[string]bool,\n\trequireAPIStyle protocol.APIStyle,\n) (*typ.Provider, *loadbalance.Service, error) {\n\tavailable := make([]*loadbalance.Service, 0)\n\tcandidateProviders := make(map[string]*typ.Provider)\n\tfor _, svc := range rule.GetActiveServices() {\n\t\tif excluded[svc.ServiceID()] {\n\t\t\tcontinue\n\t\t}\n\t\tp, err := ph.deps.Config.GetProviderByUUID(svc.Provider)\n\t\tif err != nil || p == nil {\n\t\t\tcontinue\n\t\t}\n\t\tif requireAPIStyle != \"\" && p.APIStyle != requireAPIStyle {\n\t\t\tcontinue\n\t\t}\n\t\tavailable = append(available, svc)\n\t\tcandidateProviders[svc.ServiceID()] = p\n\t}\n\tif len(available) == 0 {\n\t\treturn nil, nil, nil\n\t}\n\n\ttempRule := *rule\n\ttempRule.Services = available\n\n\t// Use tier-aware selection when the rule uses tier-based routing.\n\t// This ensures fallback respects tier ordering (T0 → T1 → T2...)\n\t// instead of using the generic load balancer which might select\n\t// any available service regardless of tier priority.\n\ttactic := rule.LBTactic.Instantiate()\n\tif tactic.GetType() == loadbalance.TacticTier {\n\t\t// TierTactic already handles tier-ordered selection with breaker awareness\n\t\tsvc := tactic.SelectService(&tempRule)\n\t\tif svc == nil {\n\t\t\treturn nil, nil, nil\n\t\t}\n\t\treturn candidateProviders[svc.ServiceID()], svc, nil\n\t}\n\n\t// For non-tier tactics, use the load balancer\n\tsvc, err := ph.deps.LoadBalancer.SelectService(&tempRule)\n\tif err != nil {\n\t\treturn nil, nil, err\n\t}\n\tif svc == nil {\n\t\treturn nil, nil, nil\n\t}\n\treturn candidateProviders[svc.ServiceID()], svc, nil\n}\n\n// dispatchAttempt is the per-attempt callback. It writes through\n// c.Writer, which is the gate during the failover loop.\ntype dispatchAttempt func(provider *typ.Provider, model string)\n\n// dispatchWithPriorityFailover runs `attempt` repeatedly, retrying on\n// retryable buffered failures until either the gate commits (the\n// stream's first real chunk reached the wire, retry impossible) or the\n// candidate pool is exhausted (the last buffered error flushes on the\n// deferred return).\n//\n// Single-service requests bypass the gate entirely: with no fallback\n// tier, failover is impossible and there is no reason to buffer.\nfunc (ph *ProtocolHandler) DispatchWithPriorityFailover(\n\tc *gin.Context,\n\trule *typ.Rule,\n\tinitialProvider *typ.Provider,\n\tinitialModel string,\n\tattempt dispatchAttempt,\n) {\n\tactiveServices := rule.GetActiveServices()\n\tif len(activeServices) <= 1 {\n\t\tattempt(initialProvider, initialModel)\n\t\treturn\n\t}\n\n\trealWriter := c.Writer\n\tgate := newFirstChunkGate(realWriter)\n\tc.Writer = gate\n\tdefer func() {\n\t\tc.Writer = realWriter\n\t\tgate.CommitIfBuffered()\n\t}()\n\n\ttried := map[string]bool{}\n\tprovider := initialProvider\n\tmodel := initialModel\n\n\t// Keep the recorder's bound service in sync per attempt so the\n\t// breaker store gets fed the right serviceID on failure.\n\trec, _ := recording.GetRecorderFromContext(c)\n\n\tfor i := 0; i < len(activeServices); i++ {\n\t\tserviceID := loadbalance.FormatServiceID(provider.UUID, model)\n\t\ttried[serviceID] = true\n\n\t\t// Update context before logging/dispatch so request-scoped observability\n\t\t// reflects the service currently being tried, and ultimately the last\n\t\t// successful service when failover succeeds.\n\t\tUpdateTrackingForFailover(c, provider, model)\n\n\t\tfields := failoverLogFields(c, rule, provider, model, serviceID)\n\t\tfields[\"stage\"] = \"failover_attempt\"\n\t\tfields[\"attempt\"] = i + 1\n\t\tfields[\"active_services\"] = len(activeServices)\n\t\tlogrus.WithContext(c.Request.Context()).WithFields(fields).Infof(\"[failover] attempt %d: trying: %s/%s\", i+1, provider.UUID, model)\n\n\t\tif rec != nil {\n\t\t\trec.SetActiveService(provider, model)\n\t\t}\n\n\t\t// One child span per attempt: the tracking context only keeps the\n\t\t// final winner (UpdateTrackingForFailover overwrites), so the span\n\t\t// is the structured record of the retry history.\n\t\tattemptSpan := ph.startFailoverAttemptSpan(c.Request.Context(), i+1, serviceID, provider.UUID)\n\n\t\terrorsBeforeAttempt := len(c.Errors)\n\t\tattempt(provider, model)\n\n\t\tsucceeded := gate.Status() >= 200 && gate.Status() < 400 && len(c.Errors) == errorsBeforeAttempt\n\t\tendFailoverAttemptSpan(attemptSpan, succeeded, gate.Status())\n\t\tif succeeded {\n\t\t\tc.Set(constant.CtxKeyRecoveredErrorCount, errorsBeforeAttempt)\n\t\t}\n\n\t\t// Once bytes reach the wire, retry is impossible, even if streaming fails.\n\t\tstatus, committed := gate.Status(), gate.Committed()\n\t\tif committed {\n\t\t\tloadbalance.RecordServiceSuccess(rule.UUID, serviceID)\n\t\t}\n\t\tchannelRefused := false\n\t\tfor _, attemptErr := range c.Errors[errorsBeforeAttempt:] {\n\t\t\tchannelRefused = channelRefused || client.IsWorkBuddyChannelRefusal(attemptErr.Err)\n\t\t}\n\t\tif committed || (!isRetryableStatus(status) && !channelRefused) {\n\t\t\tfields := failoverLogFields(c, rule, provider, model, serviceID)\n\t\t\tfields[\"stage\"] = \"failover_terminal\"\n\t\t\tfields[\"attempt\"] = i + 1\n\t\t\tfields[\"active_services\"] = len(activeServices)\n\t\t\tfields[\"status\"] = status\n\t\t\tfields[\"routed_model\"] = model\n\t\t\tfields[\"routed_provider\"] = provider.Name\n\t\t\tif succeeded {\n\t\t\t\tfields[\"stage\"] = \"failover_success\"\n\t\t\t}\n\t\t\tentry := logrus.WithContext(c.Request.Context()).WithFields(fields)\n\t\t\tswitch {\n\t\t\tcase succeeded:\n\t\t\t\tentry.Infof(\"[failover] succeeded on attempt %d with %s/%s\", i+1, provider.UUID, model)\n\t\t\tcase committed:\n\t\t\t\tentry.Errorf(\"[failover] stream failed after response committed on attempt %d with %s/%s\", i+1, provider.UUID, model)\n\t\t\tdefault:\n\t\t\t\tentry.Warnf(\"[failover] attempt %d returned status %d with %s/%s\", i+1, status, provider.UUID, model)\n\t\t\t}\n\t\t\treturn\n\t\t}\n\n\t\t// Health owns rate-limit/auth availability across requests, while the\n\t\t// breaker owns transient 5xx failures within a rule. A successful\n\t\t// fallback means final usage tracking only sees the fallback's success,\n\t\t// so record a failed 429 attempt here or the next request would select\n\t\t// the rate-limited service again before SmartRouting/LB evaluation.\n\t\tif ph.deps.HealthMonitor != nil {\n\t\t\tswitch status {\n\t\t\tcase http.StatusTooManyRequests:\n\t\t\t\tph.deps.HealthMonitor.ReportRateLimit(serviceID)\n\t\t\tcase http.StatusUnauthorized, http.StatusForbidden:\n\t\t\t\t// Same reasoning as the 429 case: the fallback's success is all\n\t\t\t\t// the final usage tracking sees, so the broken credential would\n\t\t\t\t// keep winning selection on every subsequent request.\n\t\t\t\tph.deps.HealthMonitor.ReportAuthError(serviceID, status)\n\t\t\t}\n\t\t}\n\n\t\t// A channel refusal does not indicate a transient service outage.\n\t\tif !channelRefused {\n\t\t\tloadbalance.RecordServiceFailure(rule.UUID, serviceID)\n\t\t\tstate := loadbalance.DefaultBreakerStore().Get(rule.UUID, serviceID).State()\n\t\t\tfields = failoverLogFields(c, rule, provider, model, serviceID)\n\t\t\tfields[\"stage\"] = \"breaker_failure_recorded\"\n\t\t\tfields[\"rule_uuid\"] = rule.UUID\n\t\t\tfields[\"status\"] = status\n\t\t\tfields[\"breaker_state\"] = state.String()\n\t\t\tlogrus.WithContext(c.Request.Context()).WithFields(fields).Warnf(\"[breaker] recorded failure for %s; state=%s\", serviceID, state.String())\n\t\t}\n\n\t\tfields = failoverLogFields(c, rule, provider, model, serviceID)\n\t\tfields[\"stage\"] = \"failover_attempt_failed\"\n\t\tfields[\"attempt\"] = i + 1\n\t\tfields[\"active_services\"] = len(activeServices)\n\t\tfields[\"status\"] = status\n\t\tfields[\"retryable\"] = true\n\t\tlogrus.WithContext(c.Request.Context()).WithFields(fields).Warnf(\"[failover] attempt %d failed with retryable status %d on %s/%s\",\n\t\t\ti+1, status, provider.UUID, model)\n\n\t\t// Pass \"\" so the candidate pool spans all API styles: each attempt\n\t\t// re-transforms the request for the selected provider's style, so\n\t\t// heterogeneous failover (e.g. Anthropic → OpenAI) is supported.\n\t\tnextProvider, nextService, err := ph.selectFallbackService(rule, tried, \"\")\n\t\tif err != nil {\n\t\t\tfields := failoverLogFields(c, rule, provider, model, serviceID)\n\t\t\tfields[\"stage\"] = \"failover_error\"\n\t\t\tfields[\"attempt\"] = i + 1\n\t\t\tfields[\"active_services\"] = len(activeServices)\n\t\t\tfields[\"status\"] = status\n\t\t\tfields[\"error\"] = err.Error()\n\t\t\tlogrus.WithContext(c.Request.Context()).WithFields(fields).Warnf(\"[failover] load balancer failed selecting fallback after %d attempt(s) status=%d: %v\", i+1, status, err)\n\t\t\treturn\n\t\t}\n\t\tif nextProvider == nil || nextService == nil {\n\t\t\tfields := failoverLogFields(c, rule, provider, model, serviceID)\n\t\t\tfields[\"stage\"] = \"failover_exhausted\"\n\t\t\tfields[\"attempt\"] = i + 1\n\t\t\tfields[\"active_services\"] = len(activeServices)\n\t\t\tfields[\"status\"] = status\n\t\t\tlogrus.WithContext(c.Request.Context()).WithFields(fields).Warnf(\"[failover] giving up after %d attempt(s) status=%d (no more services)\", i+1, status)\n\t\t\treturn\n\t\t}\n\n\t\tnextServiceID := loadbalance.FormatServiceID(nextProvider.UUID, nextService.Model)\n\t\tfields = failoverLogFields(c, rule, provider, model, serviceID)\n\t\tfields[\"stage\"] = \"failover_retry\"\n\t\tfields[\"attempt\"] = i + 1\n\t\tfields[\"active_services\"] = len(activeServices)\n\t\tfields[\"status\"] = status\n\t\tfields[\"from_service\"] = serviceID\n\t\tfields[\"to_service\"] = nextServiceID\n\t\tfields[\"to_provider\"] = nextProvider.Name\n\t\tfields[\"to_model\"] = nextService.Model\n\t\tlogrus.WithContext(c.Request.Context()).WithFields(fields).Warnf(\"[failover] attempt %d failed with %d, retrying with %s/%s\",\n\t\t\ti+1, status, nextProvider.UUID, nextService.Model)\n\n\t\tgate.Discard()\n\t\tprovider = nextProvider\n\t\tmodel = nextService.Model\n\t}\n}\n\nfunc failoverLogFields(c *gin.Context, rule *typ.Rule, provider *typ.Provider, model, serviceID string) logrus.Fields {\n\tfields := logrus.Fields{\n\t\t\"service\":       serviceID,\n\t\t\"attempt_model\": model,\n\t}\n\tif provider != nil {\n\t\tfields[\"provider\"] = provider.Name\n\t\tfields[\"provider_uuid\"] = provider.UUID\n\t}\n\tif rule != nil {\n\t\tfields[\"rule_uuid\"] = rule.UUID\n\t\tfields[\"request_model\"] = rule.RequestModel\n\t\tfields[\"scenario\"] = string(rule.GetScenario())\n\t\tfields[\"lb_tactic\"] = rule.GetTacticType().String()\n\t}\n\tif c != nil {\n\t\tif requestModel := c.GetString(ContextKeyRequestModel); requestModel != \"\" {\n\t\t\tfields[\"request_model\"] = requestModel\n\t\t}\n\t\tif scenario := c.GetString(ContextKeyScenario); scenario != \"\" {\n\t\t\tfields[\"scenario\"] = scenario\n\t\t}\n\t\tif tactic := c.GetString(ContextKeyLBTactic); tactic != \"\" {\n\t\t\tfields[\"lb_tactic\"] = tactic\n\t\t}\n\t}\n\treturn fields\n}\n"
    },
    {
      "path": "internal/routing/stage_health.go",
      "content": "package routing\n\nimport (\n\t\"context\"\n\n\t\"github.com/sirupsen/logrus\"\n\n\t\"github.com/tingly-dev/tingly-box/internal/loadbalance\"\n)\n\n// HealthStage filters unhealthy services from the context.\n// It runs first and narrows ctx.CandidateServices.\ntype HealthStage struct {\n\tfilter *HealthFilter\n}\n\n// NewHealthStage creates a new health stage with the given health filter\nfunc NewHealthStage(filter *HealthFilter) *HealthStage {\n\treturn &HealthStage{filter: filter}\n}\n\nfunc (s *HealthStage) Name() string {\n\treturn SourceHealth\n}\n\nfunc (s *HealthStage) Evaluate(ctx *SelectionContext, candidates []*loadbalance.Service) ([]*loadbalance.Service, *SelectionResult, error) {\n\tif len(candidates) == 0 {\n\t\treturn candidates, nil, nil\n\t}\n\n\t// If no health filter configured, pass through unchanged\n\tif s.filter == nil {\n\t\treturn candidates, nil, nil\n\t}\n\n\tbefore := len(candidates)\n\thealthy := s.filter.Filter(candidates)\n\n\t// Degrade, don't disappear: if every candidate is unhealthy, keep the full\n\t// set rather than emptying it — mirrors LoadBalancer.SelectService, so the\n\t// caller still gets a service (and the real upstream 429/auth) instead of a\n\t// \"no service available\" routing error.\n\tif before > 0 && len(healthy) == 0 {\n\t\tlogrus.WithContext(selectionLogContext(ctx)).WithFields(logrus.Fields{\n\t\t\t\"stage\":      \"routing_health_degrade\",\n\t\t\t\"rule_uuid\":  selectionRuleUUID(ctx),\n\t\t\t\"candidates\": before,\n\t\t}).Warnf(\"[health] all %d candidates unhealthy; keeping the full set (degrade)\", before)\n\t\treturn candidates, nil, nil\n\t}\n\n\tfilteredCount := before - len(healthy)\n\n\tif filteredCount > 0 {\n\t\tlogrus.WithContext(selectionLogContext(ctx)).WithFields(logrus.Fields{\n\t\t\t\"stage\":           \"routing_health_filtered\",\n\t\t\t\"rule_uuid\":       selectionRuleUUID(ctx),\n\t\t\t\"filtered_count\":  filteredCount,\n\t\t\t\"remaining_count\": len(healthy),\n\t\t\t\"candidate_count\": before,\n\t\t}).Warnf(\"[health] Filtered %d unhealthy services, %d remaining (of %d total)\",\n\t\t\tfilteredCount, len(healthy), before)\n\t\t// Log each filtered service for debugging\n\t\tfor _, svc := range candidates {\n\t\t\tif !s.filter.IsHealthy(svc.ServiceID()) {\n\t\t\t\tlogrus.WithContext(selectionLogContext(ctx)).WithFields(logrus.Fields{\n\t\t\t\t\t\"stage\":         \"routing_health_filtered_service\",\n\t\t\t\t\t\"rule_uuid\":     selectionRuleUUID(ctx),\n\t\t\t\t\t\"service\":       svc.ServiceID(),\n\t\t\t\t\t\"provider_uuid\": svc.Provider,\n\t\t\t\t\t\"model\":         svc.Model,\n\t\t\t\t\t\"reason\":        \"rate_limited_or_auth_error\",\n\t\t\t\t}).Warnf(\"[health] Service %s:%s is unhealthy (rate limited/auth error)\",\n\t\t\t\t\tsvc.Provider, svc.Model)\n\t\t\t}\n\t\t}\n\t}\n\n\t// Continue pipeline (don't select, just filter)\n\treturn healthy, nil, nil\n}\n\nfunc selectionLogContext(ctx *SelectionContext) context.Context {\n\tif ctx != nil && ctx.GinContext != nil && ctx.GinContext.Request != nil {\n\t\treturn ctx.GinContext.Request.Context()\n\t}\n\treturn context.Background()\n}\n\nfunc selectionRuleUUID(ctx *SelectionContext) string {\n\tif ctx != nil && ctx.Rule != nil {\n\t\treturn ctx.Rule.UUID\n\t}\n\treturn \"\"\n}\n"
    },
    {
      "path": "internal/middleware/auth.go",
      "content": "package middleware\n\nimport (\n\t\"crypto/rsa\"\n\t\"crypto/x509\"\n\t\"encoding/pem\"\n\t\"errors\"\n\t\"fmt\"\n\t\"net/http\"\n\t\"os\"\n\t\"strings\"\n\t\"time\"\n\n\t\"github.com/gin-gonic/gin\"\n\t\"github.com/golang-jwt/jwt/v5\"\n\t\"github.com/tingly-dev/tingly-box/internal/config\"\n\t\"github.com/tingly-dev/tingly-box/internal/constant\"\n\t\"github.com/tingly-dev/tingly-box/internal/db\"\n\t\"github.com/tingly-dev/tingly-box/pkg/auth\"\n)\n\n// AuthMiddleware provides authentication middleware for different types of authentication\ntype AuthMiddleware struct {\n\tconfig          *config.Config\n\tjwtManager      *auth.JWTManager\n\tapiTokenManager *auth.APITokenManager\n\tapiTokenStore   APITokenStore\n}\n\n// APITokenStore interface for token validation (abstracted for testability)\ntype APITokenStore interface {\n\tValidateToken(tokenID string) (*db.APITokenRecord, error)\n\tUpdateLastUsed(tokenID string) error\n}\n\n// ErrorResponse represents an error response\ntype ErrorResponse struct {\n\tError ErrorDetail `json:\"error\"`\n}\n\n// abortWithError sends an error response and adds the error to gin context for logging\nfunc abortWithError(c *gin.Context, statusCode int, message string, errorType string) {\n\t// Add error to context so logging middleware can capture it\n\tc.Error(fmt.Errorf(\"%s: %s\", errorType, message)).SetType(gin.ErrorTypePublic)\n\n\t// Send JSON response\n\tc.JSON(statusCode, ErrorResponse{\n\t\tError: ErrorDetail{\n\t\t\tMessage: message,\n\t\t\tType:    errorType,\n\t\t},\n\t})\n\tc.Abort()\n}\n\n// ErrorDetail represents error details\ntype ErrorDetail struct {\n\tMessage string `json:\"message\"`\n\tType    string `json:\"type\"`\n\tCode    string `json:\"code,omitempty\"`\n}\n\n// NewAuthMiddleware creates a new authentication middleware\nfunc NewAuthMiddleware(cfg *config.Config, jwtManager *auth.JWTManager, apiTokenManager *auth.APITokenManager, apiTokenStore APITokenStore) *AuthMiddleware {\n\treturn &AuthMiddleware{\n\t\tconfig:          cfg,\n\t\tjwtManager:      jwtManager,\n\t\tapiTokenManager: apiTokenManager,\n\t\tapiTokenStore:   apiTokenStore,\n\t}\n}\n\ntype enterpriseContextClaims struct {\n\tUserID       string\n\tDepartmentID string\n\tKeyPrefix    string\n\tTier         string\n\tJTI          string\n}\n\nfunc containsFold(items []string, target string) bool {\n\tfor _, item := range items {\n\t\tif strings.EqualFold(strings.TrimSpace(item), strings.TrimSpace(target)) {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\nfunc resolveSecretRef(raw string) (string, error) {\n\tref := strings.TrimSpace(raw)\n\tif ref == \"\" {\n\t\treturn \"\", nil\n\t}\n\tif strings.HasPrefix(ref, \"env:\") {\n\t\treturn strings.TrimSpace(os.Getenv(strings.TrimSpace(strings.TrimPrefix(ref, \"env:\")))), nil\n\t}\n\tif strings.HasPrefix(ref, \"file:\") {\n\t\tpath := strings.TrimSpace(strings.TrimPrefix(ref, \"file:\"))\n\t\tcontent, err := os.ReadFile(path)\n\t\tif err != nil {\n\t\t\treturn \"\", err\n\t\t}\n\t\treturn strings.TrimSpace(string(content)), nil\n\t}\n\tif st, err := os.Stat(ref); err == nil && !st.IsDir() {\n\t\tcontent, readErr := os.ReadFile(ref)\n\t\tif readErr != nil {\n\t\t\treturn \"\", readErr\n\t\t}\n\t\treturn strings.TrimSpace(string(content)), nil\n\t}\n\treturn ref, nil\n}\n\nfunc parseRSAPublicKeyFromPEM(raw string) (*rsa.PublicKey, error) {\n\tblock, _ := pem.Decode([]byte(raw))\n\tif block == nil {\n\t\treturn nil, errors.New(\"invalid pem block\")\n\t}\n\tif key, err := x509.ParsePKIXPublicKey(block.Bytes); err == nil {\n\t\trsaKey, ok := key.(*rsa.PublicKey)\n\t\tif !ok {\n\t\t\treturn nil, errors.New(\"public key is not RSA\")\n\t\t}\n\t\treturn rsaKey, nil\n\t}\n\tcert, certErr := x509.ParseCertificate(block.Bytes)\n\tif certErr == nil {\n\t\tif rsaKey, ok := cert.PublicKey.(*rsa.PublicKey); ok {\n\t\t\treturn rsaKey, nil\n\t\t}\n\t}\n\treturn nil, errors.New(\"failed to parse rsa public key\")\n}\n\nfunc verifyEnterpriseContextJWT(cfg *config.Config, rawToken string) (*enterpriseContextClaims, error) {\n\ttokenString := strings.TrimSpace(rawToken)\n\tif tokenString == \"\" || cfg == nil {\n\t\treturn nil, nil\n\t}\n\tjwtCfg := cfg.EnterpriseContextJWT\n\tif !jwtCfg.Enabled {\n\t\treturn nil, nil\n\t}\n\n\tclockSkew := time.Duration(jwtCfg.ClockSkewSeconds) * time.Second\n\tparsed, err := jwt.Parse(tokenString, func(token *jwt.Token) (interface{}, error) {\n\t\talg := strings.ToUpper(strings.TrimSpace(token.Method.Alg()))\n\t\tif len(jwtCfg.AlgAllowlist) > 0 && !containsFold(jwtCfg.AlgAllowlist, alg) {\n\t\t\treturn nil, fmt.Errorf(\"algorithm %s is not allowed\", alg)\n\t\t}\n\t\tswitch alg {\n\t\tcase \"HS256\":\n\t\t\tsecret, secretErr := resolveSecretRef(jwtCfg.HS256SecretRef)\n\t\t\tif secretErr != nil {\n\t\t\t\treturn nil, secretErr\n\t\t\t}\n\t\t\tif strings.TrimSpace(secret) == \"\" {\n\t\t\t\treturn nil, errors.New(\"hs256 secret is empty\")\n\t\t\t}\n\t\t\treturn []byte(secret), nil\n\t\tcase \"RS256\":\n\t\t\t// If no public keys were provided, fall back to RS256PublicKeyRef.\n\t\t\tif len(jwtCfg.PublicKeys) == 0 && strings.TrimSpace(jwtCfg.RS256PublicKeyRef) != \"\" {\n\t\t\t\tref, refErr := resolveSecretRef(jwtCfg.RS256PublicKeyRef)\n\t\t\t\tif refErr == nil && strings.TrimSpace(ref) != \"\" {\n\t\t\t\t\tif pub, parseErr := parseRSAPublicKeyFromPEM(ref); parseErr == nil {\n\t\t\t\t\t\treturn pub, nil\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t}\n\t\t\tkid, _ := token.Header[\"kid\"].(string)\n\t\t\tkid = strings.TrimSpace(kid)\n\t\t\tfor _, item := range jwtCfg.PublicKeys {\n\t\t\t\tif kid != \"\" && strings.TrimSpace(item.KID) != kid {\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\tpub, parseErr := parseRSAPublicKeyFromPEM(item.PEM)\n\t\t\t\tif parseErr != nil {\n\t\t\t\t\tcontinue\n\t\t\t\t}\n\t\t\t\treturn pub, nil\n\t\t\t}\n\t\t\tif strings.TrimSpace(jwtCfg.JWKSURL) != \"\" {\n\t\t\t\treturn nil, errors.New(\"jwks_url is configured but dynamic jwks fetch is not implemented yet\")\n\t\t\t}\n\t\t\treturn nil, errors.New(\"no rs256 public key matched\")\n\t\tdefault:\n\t\t\treturn nil, fmt.Errorf(\"unsupported jwt alg: %s\", alg)\n\t\t}\n\t}, jwt.WithLeeway(clockSkew))\n\tif err != nil || !parsed.Valid {\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\treturn nil, errors.New(\"invalid context jwt\")\n\t}\n\n\tmapClaims, ok := parsed.Claims.(jwt.MapClaims)\n\tif !ok {\n\t\treturn nil, errors.New(\"invalid jwt claims\")\n\t}\n\n\tif len(jwtCfg.AllowedIssuers) > 0 {\n\t\tissuer, _ := mapClaims.GetIssuer()\n\t\tif !containsFold(jwtCfg.AllowedIssuers, issuer) {\n\t\t\treturn nil, fmt.Errorf(\"issuer %s is not allowed\", issuer)\n\t\t}\n\t}\n\n\tif len(jwtCfg.AllowedAudiences) > 0 {\n\t\taud, audErr := mapClaims.GetAudience()\n\t\tif audErr != nil {\n\t\t\treturn nil, audErr\n\t\t}\n\t\tfound := false\n\t\tfor _, candidate := range aud {\n\t\t\tif containsFold(jwtCfg.AllowedAudiences, candidate) {\n\t\t\t\tfound = true\n\t\t\t\tbreak\n\t\t\t}\n\t\t}\n\t\tif !found {\n\t\t\treturn nil, errors.New(\"audience is not allowed\")\n\t\t}\n\t}\n\n\tuserID, _ := mapClaims[\"sub\"].(string)\n\tdepartmentID, _ := mapClaims[\"dept_id\"].(string)\n\tkeyPrefix, _ := mapClaims[\"key_prefix\"].(string)\n\ttier, _ := mapClaims[\"tier\"].(string)\n\tjti, _ := mapClaims[\"jti\"].(string)\n\n\tif strings.TrimSpace(userID) == \"\" {\n\t\treturn nil, errors.New(\"missing sub claim\")\n\t}\n\tif jwtCfg.RequireJTI && strings.TrimSpace(jti) == \"\" {\n\t\treturn nil, errors.New(\"missing jti claim\")\n\t}\n\n\treturn &enterpriseContextClaims{\n\t\tUserID:       strings.TrimSpace(userID),\n\t\tDepartmentID: strings.TrimSpace(departmentID),\n\t\tKeyPrefix:    strings.TrimSpace(keyPrefix),\n\t\tTier:         strings.TrimSpace(tier),\n\t\tJTI:          strings.TrimSpace(jti),\n\t}, nil\n}\n\n// UserAuthMiddleware middleware for UI and control API authentication\nfunc (am *AuthMiddleware) UserAuthMiddleware() gin.HandlerFunc {\n\treturn func(c *gin.Context) {\n\t\tauthHeader := c.GetHeader(\"Authorization\")\n\t\tif authHeader == \"\" {\n\t\t\tabortWithError(c, http.StatusUnauthorized, \"User authorization header required\", \"invalid_request_error\")\n\t\t\treturn\n\t\t}\n\n\t\t// Extract token from \"Bearer <token>\" format\n\t\ttokenParts := strings.Split(authHeader, \" \")\n\t\tif len(tokenParts) != 2 || tokenParts[0] != \"Bearer\" {\n\t\t\tabortWithError(c, http.StatusUnauthorized, \"Invalid user authorization header format. Expected: 'Bearer <token>'\", \"invalid_request_error\")\n\t\t\treturn\n\t\t}\n\n\t\ttoken := tokenParts[1]\n\n\t\t// Check against global config user token first\n\t\tcfg := am.config\n\t\tif cfg != nil && cfg.HasUserToken() {\n\t\t\tconfigToken := cfg.GetUserToken()\n\n\t\t\t// Remove \"Bearer \" prefix if present in the token\n\t\t\tif strings.HasPrefix(token, \"Bearer \") {\n\t\t\t\ttoken = token[7:]\n\t\t\t}\n\n\t\t\t// Direct token comparison\n\t\t\tif token == configToken || strings.TrimPrefix(token, \"Bearer \") == configToken {\n\t\t\t\t// Token matches the one in global config, allow access\n\t\t\t\t// For UI user authentication, set user_id to default admin\n\t\t\t\t// This matches the migrated user_id in usage_records\n\t\t\t\tc.Set(constant.CtxKeyUserID, db.DefaultAdminUserID)\n\t\t\t\tc.Next()\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\n\t\tabortWithError(c, http.StatusUnauthorized, \"Invalid user authorization token.\", \"invalid_request_error\")\n\t}\n}\n\n// ModelAuthMiddleware middleware for OpenAI and Anthropic API authentication\n// The auth will support both `Authorization` and `X-Api-Key`\n// Supports three authentication methods (in order of precedence):\n// 1. JWT API tokens (when multi-tenant is enabled)\n// 2. Global config model token (backward compatibility)\n// 3. Enterprise context JWT (X-TBE-Context-JWT header)\nfunc (am *AuthMiddleware) ModelAuthMiddleware() gin.HandlerFunc {\n\treturn func(c *gin.Context) {\n\t\tauthHeader := c.GetHeader(\"Authorization\")\n\t\txApiKey := c.GetHeader(\"X-Api-Key\")\n\t\tif authHeader == \"\" && xApiKey == \"\" {\n\t\t\tabortWithError(c, http.StatusUnauthorized, \"Model authorization header required\", \"invalid_request_error\")\n\t\t\treturn\n\t\t}\n\n\t\tif authHeader == \"\" {\n\t\t\tauthHeader = xApiKey\n\t\t}\n\n\t\ttoken := authHeader\n\t\t// Remove \"Bearer \" prefix if present in the token\n\t\tif strings.HasPrefix(token, \"Bearer \") {\n\t\t\ttoken = token[7:]\n\t\t}\n\t\ttoken = strings.TrimSpace(token)\n\t\txApiKey = strings.TrimSpace(xApiKey)\n\n\t\tcfg := am.config\n\n\t\t// Try API token authentication first (if multi-tenant is enabled)\n\t\t// Check if token has tb-share- prefix\n\t\tif cfg != nil && cfg.IsMultiTenantEnabled() && am.apiTokenStore != nil {\n\t\t\tif strings.HasPrefix(token, \"tb-share-\") {\n\t\t\t\t// This is an API token, validate it directly from database\n\t\t\t\ttokenRecord, validateErr := am.apiTokenStore.ValidateToken(token)\n\t\t\t\tif validateErr == nil && tokenRecord != nil {\n\t\t\t\t\tif tokenRecord.TeamID == \"\" {\n\t\t\t\t\t\tabortWithError(c, http.StatusUnauthorized, \"Sharing key has no team binding\", \"invalid_token_error\")\n\t\t\t\t\t\treturn\n\t\t\t\t\t}\n\t\t\t\t\t// A sharing key is a team-scoped model credential, not a\n\t\t\t\t\t// second global model token. Authorize the concrete Gin route\n\t\t\t\t\t// template as well as the scenario parameter so new model\n\t\t\t\t\t// surfaces fail closed and a client cannot select a suffix\n\t\t\t\t\t// such as team:<other-scope>.\n\t\t\t\t\tif !sharingKeyCanAccessModelSurface(c) {\n\t\t\t\t\t\tabortWithError(c, http.StatusForbidden, \"Sharing key is restricted to the team model endpoint\", \"forbidden_error\")\n\t\t\t\t\t\treturn\n\t\t\t\t\t}\n\n\t\t\t\t\t// Token is valid and enabled\n\t\t\t\t\tc.Set(constant.CtxKeyAuthKind, constant.AuthKindSharingKey)\n\t\t\t\t\tc.Set(constant.CtxKeyUserID, tokenRecord.UserID)\n\t\t\t\t\tc.Set(constant.CtxKeyTeamID, tokenRecord.TeamID)\n\n\t\t\t\t\t// Update last used asynchronously\n\t\t\t\t\tgo am.apiTokenStore.UpdateLastUsed(tokenRecord.TokenID)\n\n\t\t\t\t\tc.Next()\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\n\t\t// Check global config model token (backward compatibility)\n\t\tif cfg == nil || !cfg.HasModelToken() {\n\t\t\tabortWithError(c, http.StatusInternalServerError, \"config or config model token missing\", \"invalid_request_error\")\n\t\t\treturn\n\t\t}\n\n\t\t// If global token is disabled and multi-tenant is enabled, reject\n\t\tif cfg.IsMultiTenantEnabled() && cfg.IsGlobalTokenDisabled() {\n\t\t\tabortWithError(c, http.StatusUnauthorized, \"Global token disabled, use API token\", \"invalid_token_error\")\n\t\t\treturn\n\t\t}\n\n\t\tconfigToken := cfg.GetModelToken()\n\n\t\t// Direct token comparison\n\t\tif token == configToken || xApiKey == configToken {\n\t\t\t// Set UserID to default admin for usage tracking consistency\n\t\t\t// This matches the migrated user_id values in usage_records\n\t\t\tc.Set(constant.CtxKeyAuthKind, constant.AuthKindGlobalModelToken)\n\t\t\tc.Set(constant.CtxKeyUserID, db.DefaultAdminUserID)\n\t\t\tcontextJWT := strings.TrimSpace(c.GetHeader(\"X-TBE-Context-JWT\"))\n\t\t\tif contextJWT != \"\" {\n\t\t\t\tclaims, verifyErr := verifyEnterpriseContextJWT(cfg, contextJWT)\n\t\t\t\tif verifyErr != nil {\n\t\t\t\t\tabortWithError(c, http.StatusUnauthorized, \"Invalid enterprise context jwt\", \"invalid_request_error\")\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tif claims != nil {\n\t\t\t\t\tc.Set(constant.CtxKeyEnterpriseUserID, claims.UserID)\n\t\t\t\t\tc.Set(constant.CtxKeyEnterpriseDepartmentID, claims.DepartmentID)\n\t\t\t\t\tc.Set(constant.CtxKeyEnterpriseKeyPrefix, claims.KeyPrefix)\n\t\t\t\t\tc.Set(constant.CtxKeyEnterpriseUserTier, claims.Tier)\n\t\t\t\t\tc.Set(constant.CtxKeyEnterpriseContextJTI, claims.JTI)\n\t\t\t\t\tc.Set(constant.CtxKeyEnterpriseContextVerified, true)\n\t\t\t\t}\n\t\t\t}\n\t\t\tc.Next()\n\t\t\treturn\n\t\t}\n\n\t\t// Enterprise short-lived access token authentication.\n\t\trequestToken := token\n\t\tif requestToken == \"\" {\n\t\t\trequestToken = xApiKey\n\t\t}\n\t\tif strings.HasPrefix(strings.TrimSpace(requestToken), \"sk-tbe-\") {\n\t\t\tabortWithError(c, http.StatusUnauthorized, \"Virtual key must be used through TBE /tbe/* endpoints\", \"invalid_request_error\")\n\t\t\treturn\n\t\t}\n\n\t\tabortWithError(c, http.StatusUnauthorized, \"Invalid model authorization token.\", \"invalid_request_error\")\n\t}\n}\n\n// sharingKeyCanAccessModelSurface is the sharing-principal authorization\n// boundary. Authentication middleware is reused by both /tingly/:scenario and\n// /virtual/* routes, so checking only for a valid token would turn every\n// sharing key into a global model credential. Match the registered route shape\n// (not the raw URL) and require the bare team scenario; both /tingly/team and\n// /tingly/team/v1 endpoints use this template prefix.\nfunc sharingKeyCanAccessModelSurface(c *gin.Context) bool {\n\treturn c.Param(\"scenario\") == \"team\" &&\n\t\tstrings.HasPrefix(c.FullPath(), \"/tingly/:scenario\")\n}\n"
    },
    {
      "path": "internal/config/apply_config_dsh.go",
      "content": "package config\n\nimport (\n\t\"fmt\"\n\t\"maps\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"slices\"\n\t\"strings\"\n\n\tyamlpkg \"gopkg.in/yaml.v3\"\n)\n\n// DeepSeek Harness (dsh) config/credentials application: render and merge the\n// tingly-managed provider stanza of $DSH_HOME/settings.yaml, and the\n// tingly-managed key in $DSH_HOME/.credentials.yaml.\n//\n// dsh splits its config the same way Codex does: a settings file that\n// references credentials indirectly (apiKeyEnv names an env var rather than\n// embedding the secret) and a separate write-only credentials file. See\n// https://deepseek-harness.github.io/deepseek-harness/en/guide/providers.\n\n// dshGatewayProviderName is the tingly-box provider key written into\n// settings.yaml's `llm-pi-ai.providers` map by mergeDshSettings.\nconst dshGatewayProviderName = \"tingly-box\"\n\n// dshAPIKeyEnvName is the env var name settings.yaml's apiKeyEnv points at,\n// and the key written into .credentials.yaml. Fixed rather than\n// user-configurable: it's an implementation detail of dsh's credential\n// indirection, not a user-tunable knob.\nconst dshAPIKeyEnvName = \"TINGLY_BOX_API_KEY\"\n\n// dshHomeDir resolves $DSH_HOME, falling back to ~/.dsh when unset (dsh's\n// docs do not state a default; ~/.dsh follows the common single-dotdir\n// convention used by similar CLIs).\nfunc dshHomeDir() (string, error) {\n\tif v := strings.TrimSpace(os.Getenv(\"DSH_HOME\")); v != \"\" {\n\t\treturn v, nil\n\t}\n\thome, err := os.UserHomeDir()\n\tif err != nil {\n\t\treturn \"\", fmt.Errorf(\"failed to get home directory: %w\", err)\n\t}\n\tif home == \"\" {\n\t\treturn \"\", fmt.Errorf(\"home directory resolved to empty path\")\n\t}\n\treturn filepath.Join(home, \".dsh\"), nil\n}\n\n// DshPrefs is the typed, user-tunable surface of settings.yaml's tingly-box\n// provider entry. DefaultInput mirrors the provider-level `defaultInput` key\n// (\"text\" or \"text_image\" -> [text] / [text, image]); empty omits the key so\n// dsh treats the provider as text-only — the conservative default for models\n// tingly-box cannot verify support vision (same stance as Codex's third-party\n// defaults, see .design/codex-config.md). Protocol mirrors the provider-level\n// `api` key (see dshProtocolValues) — unlike DefaultInput, dsh has no \"omit\n// it\" state for `api`: it's a required field, so an empty/invalid Protocol\n// always falls back to dshDefaultProtocol rather than being dropped.\ntype DshPrefs struct {\n\tDefaultInput string `json:\"default_input,omitempty\"`\n\tProtocol     string `json:\"protocol,omitempty\"`\n}\n\n// dshDefaultProtocol is the wire protocol dsh talks to the tingly-box\n// provider with when Protocol is unset or invalid. Chosen for backward\n// compatibility: it's the value this stanza always wrote before Protocol\n// became user-tunable.\nconst dshDefaultProtocol = \"openai-completions\"\n\n// dshProtocolValues lists the wire protocols dsh's llm-pi-ai adapter can\n// describe with just a key, an endpoint, and headers (its `supportedProtocols()`\n// — see packages/llm/llm-pi-ai/src/provider.ts in deepseek-ai/deepseek-harness).\nvar dshProtocolValues = []string{\"openai-completions\", \"openai-responses\", \"anthropic-messages\"}\n\n// dshProtocolValue validates val against dshProtocolValues, returning the\n// trimmed value and true when it is a member, or \"\"/false otherwise (empty\n// input also yields false). Shared by toConfig (write) and DshPrefsFromConfig\n// (read) so the two stay in lockstep.\nfunc dshProtocolValue(val string) (string, bool) {\n\tval = strings.TrimSpace(val)\n\tif slices.Contains(dshProtocolValues, val) {\n\t\treturn val, true\n\t}\n\treturn \"\", false\n}\n\n// DefaultDshPrefs returns the defaults for the CLI path and no-prefs\n// fallback: DefaultInput unset (text-only), Protocol defaulting to\n// dshDefaultProtocol.\nfunc DefaultDshPrefs() *DshPrefs {\n\treturn &DshPrefs{Protocol: dshDefaultProtocol}\n}\n\n// dshDefaultInputList converts the enum value into the YAML modality list,\n// or nil for an unset/invalid value (dropped, forward-compatible).\nfunc dshDefaultInputList(val string) []string {\n\tswitch val {\n\tcase \"text\":\n\t\treturn []string{\"text\"}\n\tcase \"text_image\":\n\t\treturn []string{\"text\", \"image\"}\n\tdefault:\n\t\treturn nil\n\t}\n}\n\n// toConfig converts prefs into the provider-stanza fields it controls. Unlike\n// DefaultInput, \"api\" is always emitted — dsh requires a protocol, so a\n// nil/empty/invalid Protocol resolves to dshDefaultProtocol rather than\n// omitting the key.\nfunc (p *DshPrefs) toConfig() map[string]interface{} {\n\tprotocol := dshDefaultProtocol\n\tif p != nil {\n\t\tif v, ok := dshProtocolValue(p.Protocol); ok {\n\t\t\tprotocol = v\n\t\t}\n\t}\n\tout := map[string]interface{}{\"api\": protocol}\n\tif p == nil {\n\t\treturn out\n\t}\n\tif list := dshDefaultInputList(strings.TrimSpace(p.DefaultInput)); list != nil {\n\t\tout[\"defaultInput\"] = list\n\t}\n\treturn out\n}\n\n// DshPrefsFromConfig is the inverse of toConfig: it extracts DefaultInput and\n// Protocol from a parsed tingly-box provider stanza.\nfunc DshPrefsFromConfig(providerStanza map[string]interface{}) *DshPrefs {\n\tprefs := &DshPrefs{}\n\tif v, ok := providerStanza[\"api\"].(string); ok {\n\t\tif val, ok := dshProtocolValue(v); ok {\n\t\t\tprefs.Protocol = val\n\t\t}\n\t}\n\tlist, ok := providerStanza[\"defaultInput\"].([]interface{})\n\tif !ok || len(list) == 0 {\n\t\treturn prefs\n\t}\n\thasImage := false\n\tfor _, v := range list {\n\t\tif s, ok := v.(string); ok && s == \"image\" {\n\t\t\thasImage = true\n\t\t}\n\t}\n\tif hasImage {\n\t\tprefs.DefaultInput = \"text_image\"\n\t} else {\n\t\tprefs.DefaultInput = \"text\"\n\t}\n\treturn prefs\n}\n\n// dshProviderStanza drills into cfg[\"llm-pi-ai\"][\"providers\"][\"tingly-box\"]\n// and returns it if present.\nfunc dshProviderStanza(cfg map[string]interface{}) (map[string]interface{}, bool) {\n\troot, ok := cfg[\"llm-pi-ai\"].(map[string]interface{})\n\tif !ok {\n\t\treturn nil, false\n\t}\n\tproviders, ok := root[\"providers\"].(map[string]interface{})\n\tif !ok {\n\t\treturn nil, false\n\t}\n\tstanza, ok := providers[dshGatewayProviderName].(map[string]interface{})\n\tif !ok {\n\t\treturn nil, false\n\t}\n\treturn stanza, true\n}\n\n// ReadDshSettings reads $DSH_HOME/settings.yaml and returns the typed prefs\n// and whether a tingly-managed provider stanza exists. A missing or\n// unparseable file yields empty prefs, exists=false, so the form falls back\n// to defaults rather than erroring on first-time setup.\nfunc ReadDshSettings() (prefs *DshPrefs, exists bool, err error) {\n\tdshHome, err := dshHomeDir()\n\tif err != nil {\n\t\treturn nil, false, err\n\t}\n\ttargetPath := filepath.Join(dshHome, \"settings.yaml\")\n\n\tdata, readErr := os.ReadFile(targetPath)\n\tif readErr != nil {\n\t\treturn DefaultDshPrefs(), false, nil\n\t}\n\n\tcfg := map[string]interface{}{}\n\tif err := yamlpkg.Unmarshal(data, &cfg); err != nil {\n\t\treturn DefaultDshPrefs(), false, nil\n\t}\n\n\tstanza, ok := dshProviderStanza(cfg)\n\tif !ok {\n\t\treturn DefaultDshPrefs(), false, nil\n\t}\n\treturn DshPrefsFromConfig(stanza), true, nil\n}\n\n// ApplyDshSettings merges tingly-box's provider entry into\n// $DSH_HOME/settings.yaml.\n//\n// MERGE semantics: only the `llm-pi-ai.providers.tingly-box` stanza is\n// overwritten; everything else the user has in settings.yaml — other\n// providers, unrelated top-level keys — is left alone. The previous file (if\n// any) is backed up before rewrite.\nfunc ApplyDshSettings(baseURL string, models []string, prefs *DshPrefs) (*ApplyResult, error) {\n\tdshHome, err := dshHomeDir()\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\ttargetPath := filepath.Join(dshHome, \"settings.yaml\")\n\tresult := &ApplyResult{}\n\n\tif err := os.MkdirAll(dshHome, 0755); err != nil {\n\t\tresult.Message = fmt.Sprintf(\"Failed to create directory: %v\", err)\n\t\treturn result, nil\n\